CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$ BEGIN CREATE TYPE role AS ENUM ('employee','hr','hr_lead','admin'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE workflow_status AS ENUM ('draft','submitted','hr_proposed','approved','rejected','withdrawn','reopened'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE actor_role AS ENUM ('employee','hr','hr_lead','admin','system'); EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, timezone text NOT NULL DEFAULT 'Asia/Yekaterinburg', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS departments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, headcount integer NOT NULL DEFAULT 0 CHECK (headcount >= 0), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,name));
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), login text NOT NULL, full_name text NOT NULL, password_hash text NOT NULL, role role NOT NULL DEFAULT 'employee', is_active boolean NOT NULL DEFAULT true, oidc_subject text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,login));
CREATE TABLE IF NOT EXISTS department_assignments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), department_id uuid NOT NULL REFERENCES departments(id), valid_from date NOT NULL, valid_to date, job_title text, is_critical boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (valid_to IS NULL OR valid_to >= valid_from));
CREATE INDEX IF NOT EXISTS department_assignments_user_dates_idx ON department_assignments(user_id,valid_from,valid_to);
CREATE TABLE IF NOT EXISTS sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS sessions_user_idx ON sessions(user_id);

CREATE TABLE IF NOT EXISTS overtime_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id), year integer NOT NULL CHECK (year BETWEEN 2020 AND 2100), month integer NOT NULL CHECK (month BETWEEN 1 AND 12), status workflow_status NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1 CHECK (version > 0), zero_confirmed boolean NOT NULL DEFAULT false, submitted_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,year,month));
CREATE INDEX IF NOT EXISTS overtime_reports_queue_idx ON overtime_reports(organization_id,status,year,month);
CREATE TABLE IF NOT EXISTS overtime_entries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), report_id uuid NOT NULL REFERENCES overtime_reports(id) ON DELETE CASCADE, work_date date NOT NULL, minutes integer NOT NULL CHECK (minutes IN (5,10,15,30,60)), source actor_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(report_id,work_date));

CREATE TABLE IF NOT EXISTS vacation_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), user_id uuid NOT NULL REFERENCES users(id), year integer NOT NULL CHECK (year BETWEEN 2020 AND 2100), allowance_days integer NOT NULL DEFAULT 28 CHECK (allowance_days >= 0), status workflow_status NOT NULL DEFAULT 'draft', version integer NOT NULL DEFAULT 1 CHECK (version > 0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,year));
CREATE TABLE IF NOT EXISTS vacation_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), plan_id uuid NOT NULL REFERENCES vacation_plans(id) ON DELETE CASCADE, starts_on date NOT NULL, ends_on date NOT NULL, source actor_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(ends_on >= starts_on));
CREATE INDEX IF NOT EXISTS vacation_periods_dates_idx ON vacation_periods(starts_on,ends_on);

CREATE TABLE IF NOT EXISTS revisions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, version integer NOT NULL, actor_id uuid REFERENCES users(id), actor_role actor_role NOT NULL, reason text, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(aggregate_type,aggregate_id,version));
CREATE TABLE IF NOT EXISTS approval_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), aggregate_type text NOT NULL, aggregate_id uuid NOT NULL, from_status workflow_status NOT NULL, to_status workflow_status NOT NULL, actor_id uuid NOT NULL REFERENCES users(id), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS department_absence_rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), department_id uuid NOT NULL REFERENCES departments(id), max_absent integer, min_present integer, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(max_absent IS NULL OR max_absent >= 0), CHECK(min_present IS NULL OR min_present >= 0));
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), kind text NOT NULL, payload jsonb NOT NULL, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, payload jsonb NOT NULL, processed_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id), actor_id uuid REFERENCES users(id), action text NOT NULL, object_type text NOT NULL, object_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, occurred_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS audit_events_object_idx ON audit_events(object_type,object_id,occurred_at);

CREATE TABLE IF NOT EXISTS schema_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
